begin;

create table if not exists public.house_of_the_dragon_tree (
  id text primary key,
  data jsonb not null,
  version bigint not null default 1 check (version >= 1),
  updated_at timestamptz not null default now(),
  constraint house_of_the_dragon_tree_main_only check (id = 'main')
);

create table if not exists public.house_of_the_dragon_tree_revisions (
  id bigint generated by default as identity primary key,
  tree_id text not null default 'main',
  data jsonb not null,
  version bigint not null check (version >= 1),
  created_at timestamptz not null default now()
);

create index if not exists house_of_the_dragon_tree_revisions_created_idx
  on public.house_of_the_dragon_tree_revisions(tree_id, created_at desc);

alter table public.house_of_the_dragon_tree enable row level security;
alter table public.house_of_the_dragon_tree_revisions enable row level security;

-- The lineage is read and written server-side. Browser clients do not need direct
-- table access; the service-role client bypasses RLS after the site has performed
-- its own admin authorization check.
revoke all on table public.house_of_the_dragon_tree from anon, authenticated;
revoke all on table public.house_of_the_dragon_tree_revisions from anon, authenticated;

